  "shift.deleteTooltipReady": { id: "Hapus riwayat shift ini", en: "Delete this shift record", ms: "Padam rekod syif ini", th: "ลบประวัติกะนี้", fil: "Tanggalin ang record ng shift na ito", vi: "Xóa lịch sử ca này" },
  "shift.deleteTooltipNotClosed": { id: "Tutup shift ini dulu sebelum bisa dihapus", en: "Close this shift before it can be deleted", ms: "Tutup syif ini dahulu sebelum boleh dipadam", th: "ต้องปิดกะนี้ก่อนจึงจะลบได้", fil: "Isara muna ang shift na ito bago ito matanggal", vi: "Phải đóng ca này trước khi có thể xóa" },
  "shift.edit": { id: "Edit", en: "Edit", ms: "Edit", th: "แก้ไข", fil: "I-edit", vi: "Sửa" },
