  "shift.downloadReportBtn": { id: "Download Berita Acara (PDF)", en: "Download Handover Report (PDF)", ms: "Muat Turun Laporan Serah Terima (PDF)", th: "ดาวน์โหลดรายงานส่งมอบ (PDF)", fil: "I-download ang Ulat ng Paghahanda (PDF)", vi: "Tải biên bản bàn giao (PDF)" },
  "shift.cashInLabel": { id: "Kas Masuk", en: "Cash In", ms: "Tunai Masuk", th: "เงินสดเข้า", fil: "Cash In", vi: "Tiền vào" },
  "shift.cashInHint": { id: "Semua uang tunai yang masuk ke laci shift ini — termasuk pembayaran tunai, dan uang masuk dari transaksi PPOB (mis. pembelian pulsa/token/tagihan yang dibayar tunai).", en: "All cash that came into this shift's drawer — including cash payments, and cash in from PPOB transactions (e.g. phone credit/token/bill purchases paid in cash).", ms: "Semua wang tunai yang masuk ke laci syif ini — termasuk pembayaran tunai, dan wang masuk daripada transaksi PPOB (cth. pembelian kredit/token/bil yang dibayar tunai).", th: "เงินสดทั้งหมดที่เข้าลิ้นชักในกะนี้ — รวมการชำระเงินสด และเงินเข้าจากธุรกรรม PPOB (เช่น ซื้อเติมเงิน/โทเค็น/บิลที่จ่ายเป็นเงินสด)", fil: "Lahat ng cash na pumasok sa drawer ng shift na ito — kasama ang cash payments, at cash in mula sa mga transaksyong PPOB (hal. bili ng load/token/bayad-bayarin na binayaran ng cash).", vi: "Toàn bộ tiền mặt vào ngăn kéo trong ca này — bao gồm thanh toán tiền mặt, và tiền vào từ giao dịch PPOB (vd. mua thẻ điện thoại/token/hóa đơn trả bằng tiền mặt)." },
  "shift.cashOutLabel": { id: "Kas Keluar", en: "Cash Out", ms: "Tunai Keluar", th: "เงินสดออก", fil: "Cash Out", vi: "Tiền ra" },
  "shift.cashOutHint": { id: "Semua uang tunai yang keluar dari laci shift ini — termasuk pengeluaran/beban, dan uang keluar dari transaksi PPOB (mis. tarik tunai).", en: "All cash that left this shift's drawer — including expenses, and cash out from PPOB transactions (e.g. cash withdrawal service).", ms: "Semua wang tunai yang keluar daripada laci syif ini — termasuk perbelanjaan, dan wang keluar daripada transaksi PPOB (cth. perkhidmatan pengeluaran tunai).", th: "เงินสดทั้งหมดที่ออกจากลิ้นชักในกะนี้ — รวมค่าใช้จ่าย และเงินออกจากธุรกรรม PPOB (เช่น บริการถอนเงินสด)", fil: "Lahat ng cash na lumabas sa drawer ng shift na ito — kasama ang mga gastos, at cash out mula sa mga transaksyong PPOB (hal. serbisyong pag-withdraw ng cash).", vi: "Toàn bộ tiền mặt ra khỏi ngăn kéo trong ca này — bao gồm chi phí, và tiền ra từ giao dịch PPOB (vd. dịch vụ rút tiền mặt)." },
  "shift.ppobCashNote": { id: "Termasuk dari transaksi PPOB (tarik tunai/top up/bayar tagihan dll):", en: "Includes PPOB transactions (cash withdrawal/top up/bill payment etc.):", ms: "Termasuk daripada transaksi PPOB (pengeluaran tunai/top up/bayar bil dll):", th: "รวมธุรกรรม PPOB (ถอนเงินสด/เติมเงิน/จ่ายบิล ฯลฯ):", fil: "Kasama ang mga transaksyong PPOB (cash withdrawal/top up/bayad-bayarin atbp.):", vi: "Bao gồm giao dịch PPOB (rút tiền mặt/nạp tiền/thanh toán hóa đơn v.v.):" },
  "shift.ppobCashInShort": { id: "masuk", en: "in", ms: "masuk", th: "เข้า", fil: "papasok", vi: "vào" },
  "shift.ppobCashOutShort": { id: "keluar", en: "out", ms: "keluar", th: "ออก", fil: "palabas", vi: "ra" },
  "shift.cashDropNote": { id: "Termasuk Setoran Kas (dipindahkan ke Kas Besar/Prive/dll) sebesar", en: "Includes Cash Drop (moved to Kas Besar/owner draw/etc.) of", ms: "Termasuk Setoran Tunai (dipindahkan ke Kas Besar/pengeluaran pemilik/dll) sebanyak", th: "รวมการนำเงินสดออก (ย้ายไปที่ Kas Besar/เงินถอนเจ้าของ ฯลฯ) จำนวน", fil: "Kasama ang Cash Drop (inilipat sa Kas Besar/owner draw/atbp.) na", vi: "Bao gồm khoản nộp tiền mặt (chuyển sang Kas Besar/rút của chủ v.v.) là" },
  "shift.expectedCashLabel": { id: "Ekspektasi Kas", en: "Expected Cash", ms: "Jangkaan Tunai", th: "เงินสดที่คาดไว้", fil: "Inaasahang Cash", vi: "Tiền mặt dự kiến" },
  "shift.expectedCashHint": { id: "Uang yang SEHARUSNYA ada di laci menurut catatan transaksi sistem (modal awal + uang masuk − uang keluar) — bukan hasil hitungan fisikmu.", en: "The amount that SHOULD be in the drawer according to the system's transaction records (starting cash + cash in − cash out) — not your physical count.", ms: "Jumlah yang SEPATUTNYA ada dalam laci mengikut rekod transaksi sistem (modal permulaan + tunai masuk − tunai keluar) — bukan hasil kiraan fizikal anda.", th: "จำนวนที่ควรมีในลิ้นชักตามบันทึกธุรกรรมของระบบ (เงินทุนเริ่มต้น + เงินเข้า − เงินออก) — ไม่ใช่ผลจากการนับจริงของคุณ", fil: "Ang halagang DAPAT nasa drawer batay sa record ng transaksyon ng system (panimulang cash + cash in − cash out) — hindi ang resulta ng pisikal mong bilang.", vi: "Số tiền LẼ RA phải có trong ngăn kéo theo ghi nhận giao dịch của hệ thống (vốn ban đầu + tiền vào − tiền ra) — không phải kết quả đếm thực tế của bạn." },
  "shift.cashVarianceLabel": { id: "Selisih Kas", en: "Cash Variance", ms: "Perbezaan Tunai", th: "ผลต่างเงินสด", fil: "Variance ng Cash", vi: "Chênh lệch tiền mặt" },
  "shift.cashVarianceHint": { id: "Selisih = uang hasil hitungan fisikmu dikurangi Ekspektasi Kas. Negatif berarti uang di laci kurang dari seharusnya; positif berarti lebih.", en: "Variance = your physical count minus Expected Cash. Negative means the drawer has less than it should; positive means more.", ms: "Perbezaan = hasil kiraan fizikal anda tolak Jangkaan Tunai. Negatif bermaksud wang dalam laci kurang daripada sepatutnya; positif bermaksud lebih.", th: "ผลต่าง = ยอดนับจริงของคุณลบด้วยเงินสดที่คาดไว้ ค่าติดลบหมายถึงเงินในลิ้นชักน้อยกว่าที่ควร ค่าบวกหมายถึงมากกว่า", fil: "Variance = pisikal mong bilang minus ang Inaasahang Cash. Negative ay nangangahulugang kulang ang laman ng drawer sa dapat; positive ay sobra.", vi: "Chênh lệch = số đếm thực tế trừ Tiền mặt dự kiến. Âm nghĩa là ngăn kéo có ít hơn mức lẽ ra phải có; dương nghĩa là nhiều hơn." },
