  "shift.colActualCashHint": { id: "Total uang tunai hasil hitungan fisik saat tutup shift", en: "Total cash from the physical count when the shift was closed", ms: "Jumlah wang tunai daripada kiraan fizikal semasa syif ditutup", th: "ยอดเงินสดรวมจากการนับจริงตอนปิดกะ", fil: "Kabuuang cash mula sa pisikal na bilang noong isinara ang shift", vi: "Tổng tiền mặt từ lần đếm thực tế khi đóng ca" },
