  // --- Shift history ---
  "shift.historyTitle": { id: "Riwayat Shift", en: "Shift History", ms: "Sejarah Syif", th: "ประวัติกะ", fil: "Kasaysayan ng Shift", vi: "Lịch sử ca" },
  "shift.historyDescPrefix": { id: "Setiap pergantian shift otomatis dicek selisih kas (fisik vs ekspektasi sistem) dan selisih saldo channel non-tunai — ditandai", en: "Every shift change automatically checks the cash variance (physical vs. system expectation) and the non-cash channel balance variance — flagged", ms: "Setiap pertukaran syif secara automatik menyemak perbezaan tunai (fizikal berbanding jangkaan sistem) dan perbezaan baki saluran bukan tunai — ditanda", th: "ทุกครั้งที่เปลี่ยนกะ ระบบจะตรวจสอบผลต่างเงินสด (เงินจริงเทียบกับที่ระบบคาดไว้) และผลต่างยอดคงเหลือช่องทางที่ไม่ใช่เงินสดโดยอัตโนมัติ — ทำเครื่องหมายเป็น", fil: "Bawat pagpapalit ng shift ay awtomatikong sinusuri ang variance ng cash (pisikal kumpara sa inaasahan ng system) at variance ng balanse ng non-cash channel — minarkahan", vi: "Mỗi lần đổi ca, hệ thống tự động kiểm tra chênh lệch tiền mặt (thực tế so với dự kiến của hệ thống) và chênh lệch số dư kênh phi tiền mặt — được đánh dấu" },
  "shift.historyDescRedLabel": { id: 'merah "Kurang"', en: 'red "Short"', ms: 'merah "Kurang"', th: 'สีแดง "ขาด"', fil: 'pulang "Kulang"', vi: 'màu đỏ "Thiếu"' },
  "shift.historyDescMiddle": { id: "untuk kekurangan dan", en: "for a shortage and", ms: "untuk kekurangan dan", th: "สำหรับกรณีขาด และ", fil: "para sa kakulangan at", vi: "cho trường hợp thiếu và" },
  "shift.historyDescAmberLabel": { id: 'kuning "Lebih"', en: 'amber "Over"', ms: 'kuning "Lebih"', th: 'สีเหลือง "เกิน"', fil: 'dilaw "Sobra"', vi: 'màu hổ phách "Dư"' },
  "shift.historyDescSuffix": { id: "untuk kelebihan, supaya keduanya sama-sama kelihatan, bukan cuma yang kurang.", en: "for an overage, so both are equally visible, not just shortages.", ms: "untuk kelebihan, supaya kedua-duanya sama-sama kelihatan, bukan hanya kekurangan.", th: "สำหรับกรณีเกิน เพื่อให้มองเห็นทั้งสองกรณีเท่าๆ กัน ไม่ใช่แค่กรณีที่ขาด", fil: "para sa sobra, para pareho itong makikita, hindi lang ang kakulangan.", vi: "cho trường hợp dư, để cả hai trường hợp đều dễ nhìn thấy, không chỉ riêng phần thiếu." },
