  "shift.colNonCashVariance": { id: "Selisih Non-Tunai", en: "Non-Cash Variance", ms: "Perbezaan Bukan Tunai", th: "ผลต่างที่ไม่ใช่เงินสด", fil: "Variance ng Non-Cash", vi: "Chênh lệch phi tiền mặt" },
  "shift.colNonCashVarianceHint": { id: "Total selisih (aktual vs ekspektasi) untuk semua channel non-tunai seperti GoPay/DANA/Fastpay pada shift ini", en: "Total variance (actual vs. expected) across all non-cash channels like GoPay/DANA/Fastpay for this shift", ms: "Jumlah perbezaan (sebenar berbanding jangkaan) untuk semua saluran bukan tunai seperti GoPay/DANA/Fastpay pada syif ini", th: "ผลต่างรวม (จริงเทียบกับที่คาดไว้) ของทุกช่องทางที่ไม่ใช่เงินสด เช่น GoPay/DANA/Fastpay ในกะนี้", fil: "Kabuuang variance (aktwal kumpara sa inaasahan) sa lahat ng non-cash channel tulad ng GoPay/DANA/Fastpay sa shift na ito", vi: "Tổng chênh lệch (thực tế so với dự kiến) trên tất cả các kênh phi tiền mặt như GoPay/DANA/Fastpay trong ca này" },
