  "shift.colFraud": { id: "Anti-Fraud", en: "Anti-Fraud", ms: "Anti-Fraud", th: "ป้องกันทุจริต", fil: "Anti-Fraud", vi: "Chống gian lận" },
  "shift.colFraudHint": { id: "Ditandai otomatis kalau selisih atau jumlah void/refund/hapus pada shift ini melebihi ambang batas di Pengaturan > Preferensi", en: "Auto-flagged when this shift's variance or void/refund/delete count exceeds the threshold in Settings > Preferences", ms: "Ditanda secara automatik jika perbezaan atau bilangan void/refund/padam syif ini melebihi ambang di Tetapan > Keutamaan", th: "ถูกตั้งค่าสถานะอัตโนมัติเมื่อผลต่างหรือจำนวนการยกเลิก/คืนเงิน/ลบของกะนี้เกินเกณฑ์ที่ตั้งไว้ในการตั้งค่า > การตั้งค่าที่ต้องการ", fil: "Awtomatikong minarkahan kapag ang variance o bilang ng void/refund/delete sa shift na ito ay lumampas sa threshold sa Settings > Preferences", vi: "Tự động gắn cờ khi chênh lệch hoặc số lần hủy/hoàn tiền/xóa của ca này vượt ngưỡng trong Cài đặt > Tùy chọn" },
  "shift.fraud.clean": { id: "Bersih", en: "Clean", ms: "Bersih", th: "ปกติ", fil: "Malinis", vi: "Sạch" },
  "shift.fraud.flaggedCount": { id: "{count} ditandai", en: "{count} flagged", ms: "{count} ditanda", th: "ถูกตั้งค่าสถานะ {count}", fil: "{count} minarkahan", vi: "{count} bị gắn cờ" },
  "shift.fraud.pendingReview": { id: "Menunggu review", en: "Awaiting review", ms: "Menunggu semakan", th: "รอตรวจสอบ", fil: "Naghihintay ng review", vi: "Chờ xem xét" },
