  "shift.fraud.reviewRejected": { id: "Ditolak reviewer", en: "Rejected by reviewer", ms: "Ditolak oleh penyemak", th: "ผู้ตรวจสอบปฏิเสธ", fil: "Tinanggihan ng reviewer", vi: "Người xem xét đã từ chối" },
  "shift.review.rejectNotePrompt": { id: "Catatan penolakan (opsional)?", en: "Rejection note (optional)?", ms: "Catatan penolakan (pilihan)?", th: "หมายเหตุการปฏิเสธ (ไม่บังคับ)?", fil: "Tala ng pagtanggi (opsyonal)?", vi: "Ghi chú từ chối (không bắt buộc)?" },

  // --- Alerts / confirms ---
  "shift.confirmDeleteChannel": { id: 'Hapus channel "{label}"? Akun COA yang terkait akan otomatis dihapus/diarsipkan bersamaan.', en: 'Delete channel "{label}"? Its linked COA account will be automatically deleted/archived along with it.', ms: 'Padam saluran "{label}"? Akaun COA yang berkaitan akan dipadam/diarkibkan secara automatik bersama-sama.', th: 'ลบช่องทาง "{label}" หรือไม่? บัญชี COA ที่เกี่ยวข้องจะถูกลบ/เก็บถาวรโดยอัตโนมัติไปพร้อมกัน', fil: 'Tanggalin ang channel na "{label}"? Awtomatikong matatanggal/ma-archive ang kaugnay na COA account kasabay nito.', vi: 'Xóa kênh "{label}"? Tài khoản COA liên kết sẽ tự động bị xóa/lưu trữ cùng lúc.' },
  "shift.confirmDeleteShift": { id: "Hapus riwayat shift ini (dibuka {openedAt}, kasir {staffName})? Tidak bisa dibatalkan.", en: "Delete this shift record (opened {openedAt}, cashier {staffName})? This cannot be undone.", ms: "Padam rekod syif ini (dibuka {openedAt}, juruwang {staffName})? Ini tidak boleh dibatalkan.", th: "ลบประวัติกะนี้ (เปิดเมื่อ {openedAt} แคชเชียร์ {staffName}) หรือไม่? ไม่สามารถยกเลิกได้", fil: "Tanggalin ang record ng shift na ito (binuksan {openedAt}, cashier {staffName})? Hindi na ito maibabalik.", vi: "Xóa lịch sử ca này (mở lúc {openedAt}, thu ngân {staffName})? Không thể hoàn tác." },
  "shift.confirmDeleteOpenShift": {
    id: "PERHATIAN: shift ini MASIH BERJALAN (dibuka {openedAt}, kasir {staffName}), belum ditutup. Menghapusnya akan langsung menghilangkannya dari sistem — kasir yang memakainya akan diminta buka shift baru, dan transaksi yang sudah tercatat di shift ini kehilangan tautannya. Hanya lakukan ini untuk shift yang memang error/tidak akan pernah ditutup normal. Lanjutkan hapus?",
    en: "WARNING: this shift is STILL RUNNING (opened {openedAt}, cashier {staffName}), not yet closed. Deleting it removes it from the system immediately — the cashier using it will be prompted to open a new shift, and transactions already tagged to this shift lose that link. Only do this for a shift that's genuinely broken/will never be closed normally. Continue deleting?",
    ms: "AMARAN: syif ini MASIH BERJALAN (dibuka {openedAt}, juruwang {staffName}), belum ditutup. Memadamnya akan terus menghilangkannya dari sistem — juruwang yang menggunakannya akan diminta membuka syif baharu, dan transaksi yang sudah ditandakan pada syif ini kehilangan pautan tersebut. Lakukan ini hanya untuk syif yang memang rosak/tidak akan pernah ditutup secara normal. Teruskan padam?",
    th: "คำเตือน: กะนี้ยังดำเนินการอยู่ (เปิดเมื่อ {openedAt} แคชเชียร์ {staffName}) ยังไม่ได้ปิด การลบจะทำให้หายไปจากระบบทันที — แคชเชียร์ที่ใช้งานอยู่จะถูกขอให้เปิดกะใหม่ และธุรกรรมที่บันทึกไว้ในกะนี้จะสูญเสียการเชื่อมโยง ทำเช่นนี้เฉพาะกะที่ผิดพลาดจริงๆ/จะไม่มีวันถูกปิดตามปกติเท่านั้น ดำเนินการลบต่อหรือไม่?",
    fil: "BABALA: ang shift na ito ay TUMATAKBO PA (binuksan {openedAt}, cashier {staffName}), hindi pa isinara. Ang pagtanggal nito ay agad itong aalisin sa system — ang cashier na gumagamit nito ay hihilingin na magbukas ng bagong shift, at mawawala ang link ng mga transaksyong naka-tag na sa shift na ito. Gawin lang ito kung talagang sira ang shift/hindi na ito maisasara nang normal. Ituloy ang pagtanggal?",
    vi: "CẢNH BÁO: ca này VẪN ĐANG CHẠY (mở lúc {openedAt}, thu ngân {staffName}), chưa đóng. Xóa nó sẽ loại bỏ ngay khỏi hệ thống — thu ngân đang dùng ca này sẽ được yêu cầu mở ca mới, và các giao dịch đã gắn với ca này sẽ mất liên kết đó. Chỉ làm điều này với ca thực sự bị lỗi/sẽ không bao giờ đóng bình thường được. Tiếp tục xóa?",
  },
  "shift.deleteTooltipStillOpen": { id: "Shift ini masih berjalan — hapus hanya kalau memang shift error/tidak akan ditutup normal", en: "This shift is still running — only delete if it's genuinely broken/won't be closed normally", ms: "Syif ini masih berjalan — padam hanya jika ia memang rosak/tidak akan ditutup secara normal", th: "กะนี้ยังดำเนินการอยู่ — ลบเฉพาะเมื่อผิดพลาดจริงๆ/จะไม่ถูกปิดตามปกติ", fil: "Tumatakbo pa ang shift na ito — tanggalin lang kung talagang sira/hindi na isasara nang normal", vi: "Ca này vẫn đang chạy — chỉ xóa nếu thực sự bị lỗi/sẽ không đóng bình thường được" },
  "shift.missingBalanceAlert": { id: "Saldo aktual belum diisi untuk: {list}", en: "Actual balance not yet filled in for: {list}", ms: "Baki sebenar belum diisi untuk: {list}", th: "ยังไม่ได้กรอกยอดคงเหลือจริงสำหรับ: {list}", fil: "Hindi pa napunan ang aktwal na balanse para sa: {list}", vi: "Chưa nhập số dư thực tế cho: {list}" },
  "shift.confirmCloseShift": { id: "Pastikan hitungan fisik sudah final sebelum submit — setelah ini tidak bisa diubah. Lanjutkan tutup shift?", en: "Make sure the physical count is final before submitting — it can't be changed after this. Continue closing the shift?", ms: "Pastikan kiraan fizikal sudah muktamad sebelum menghantar — selepas ini tidak boleh diubah. Teruskan menutup syif?", th: "ตรวจสอบให้แน่ใจว่าการนับจริงเป็นค่าสุดท้ายก่อนส่ง — หลังจากนี้จะไม่สามารถแก้ไขได้ ต้องการปิดกะต่อหรือไม่?", fil: "Siguraduhing final na ang pisikal na bilang bago mag-submit — hindi na ito mababago pagkatapos nito. Ituloy ang pagsasara ng shift?", vi: "Đảm bảo số đếm thực tế là số liệu cuối cùng trước khi gửi — sau bước này sẽ không thể thay đổi. Tiếp tục đóng ca?" },

