  "cashDeposit.destinationLabel": { id: "Ke Akun Kas Tujuan", en: "To Destination Cash Account", ms: "Ke Akaun Tunai Destinasi", th: "ไปยังบัญชีเงินสดปลายทาง", fil: "Sa Destination Cash Account", vi: "Đến tài khoản tiền mặt đích" },
  "cashDeposit.selectPlaceholder": { id: "Pilih", en: "Select", ms: "Pilih", th: "เลือก", fil: "Piliin", vi: "Chọn" },
  "cashDeposit.noDestinationHint": { id: "Belum ada akun kas lain — tambahkan dulu di Admin Data > Akun Kas/Bank (mis. \"Kas Besar\").", en: "No other cash account yet — add one first in Admin Data > Cash/Bank Accounts (e.g. \"Main Safe\").", ms: "Belum ada akaun tunai lain — tambah dahulu di Admin Data > Akaun Tunai/Bank (cth. \"Kas Besar\").", th: "ยังไม่มีบัญชีเงินสดอื่น — เพิ่มก่อนที่ Admin Data > บัญชีเงินสด/ธนาคาร (เช่น \"Kas Besar\")", fil: "Wala pang ibang cash account — magdagdag muna sa Admin Data > Cash/Bank Accounts (hal. \"Kas Besar\").", vi: "Chưa có tài khoản tiền mặt khác — thêm trước tại Admin Data > Tài khoản Tiền mặt/Ngân hàng (vd: \"Két lớn\")." },
  "cashDeposit.receiverLabel": { id: "Diterima/Diambil Oleh (wajib)", en: "Received/Taken By (required)", ms: "Diterima/Diambil Oleh (wajib)", th: "รับ/นำโดย (บังคับ)", fil: "Tinanggap/Kinuha ni (kailangan)", vi: "Người nhận/lấy (bắt buộc)" },
  "cashDeposit.noReceiverHint": { id: "Belum ada staf dengan role Owner/Manager/Supervisor/Accounting di outlet ini.", en: "No staff with Owner/Manager/Supervisor/Accounting role at this outlet yet.", ms: "Belum ada staf dengan role Owner/Manager/Supervisor/Accounting di outlet ini.", th: "ยังไม่มีพนักงานที่มีบทบาท Owner/Manager/Supervisor/Accounting ในสาขานี้", fil: "Wala pang staff na may role na Owner/Manager/Supervisor/Accounting sa outlet na ito.", vi: "Chưa có nhân viên nào có vai trò Owner/Manager/Supervisor/Accounting tại chi nhánh này." },
