  // --- Pindah Kas (Cash Transfer) tab ---
  "cashTransfer.formTitle": { id: "Ajukan Pindah Kas", en: "Request Cash Transfer", ms: "Mohon Pindahan Tunai", th: "ขอโอนเงินสด", fil: "Humiling ng Paglipat ng Cash", vi: "Yêu cầu chuyển quỹ tiền mặt" },
  "cashTransfer.formDesc": { id: "Untuk memindahkan saldo antar kas outlet sendiri (mis. Kas Kecil ke Kas Besar) — bukan diambil keluar seperti Setoran Kas. Setiap permintaan butuh persetujuan Owner/Manager dulu sebelum tercatat ke jurnal.", en: "For moving balance between the outlet's own cash pools (e.g. Petty Cash to Main Safe) — not taken out like Setoran Kas. Every request needs Owner/Manager approval before it's booked to the journal.", ms: "Untuk memindahkan baki antara kas outlet sendiri (cth. Kas Kecil ke Kas Besar) — bukan dikeluarkan seperti Setoran Kas. Setiap permintaan perlu kelulusan Owner/Manager dahulu sebelum dibukukan ke jurnal.", th: "สำหรับย้ายยอดคงเหลือระหว่างกระเป๋าเงินสดของร้านเอง (เช่น เงินสดย่อยไปตู้เซฟหลัก) — ไม่ใช่การนำออกแบบ Setoran Kas ทุกคำขอต้องได้รับอนุมัติจาก Owner/Manager ก่อนจึงจะบันทึกบัญชี", fil: "Para sa paglilipat ng balanse sa pagitan ng sariling cash pools ng outlet (hal. Petty Cash papunta sa Main Safe) — hindi kinukuha palabas tulad ng Setoran Kas. Bawat kahilingan ay kailangan ng pag-apruba ng Owner/Manager bago maitala sa journal.", vi: "Để chuyển số dư giữa các quỹ tiền mặt của chính cửa hàng (vd. Quỹ tiền mặt nhỏ sang Két lớn) — không phải rút ra như Setoran Kas. Mỗi yêu cầu cần Owner/Manager phê duyệt trước khi ghi vào sổ nhật ký." },
  "cashTransfer.amountLabel": { id: "Jumlah", en: "Amount", ms: "Jumlah", th: "จำนวนเงิน", fil: "Halaga", vi: "Số tiền" },
  "cashTransfer.sourceLabel": { id: "Dari Akun Kas", en: "From Cash Account", ms: "Dari Akaun Tunai", th: "จากบัญชีเงินสด", fil: "Mula sa Cash Account", vi: "Từ tài khoản tiền mặt" },
  "cashTransfer.destinationLabel": { id: "Ke Akun Kas Tujuan", en: "To Destination Cash Account", ms: "Ke Akaun Tunai Destinasi", th: "ไปยังบัญชีเงินสดปลายทาง", fil: "Sa Destination Cash Account", vi: "Đến tài khoản tiền mặt đích" },
  "cashTransfer.submitBtn": { id: "Ajukan Pindah Kas", en: "Request Cash Transfer", ms: "Mohon Pindahan Tunai", th: "ขอโอนเงินสด", fil: "Humiling ng Paglipat ng Cash", vi: "Yêu cầu chuyển quỹ" },
  "cashTransfer.submitted": { id: "Permintaan pindah kas diajukan — menunggu persetujuan Owner/Manager sebelum tercatat ke jurnal.", en: "Cash transfer request submitted — waiting for Owner/Manager approval before it's booked to the journal.", ms: "Permintaan pindahan tunai dihantar — menunggu kelulusan Owner/Manager sebelum dibukukan ke jurnal.", th: "ส่งคำขอโอนเงินสดแล้ว — รอการอนุมัติจาก Owner/Manager ก่อนบันทึกบัญชี", fil: "Naisumite ang kahilingan sa paglipat ng cash — hinihintay ang pag-apruba ng Owner/Manager bago maitala sa journal.", vi: "Đã gửi yêu cầu chuyển quỹ tiền mặt — chờ Owner/Manager phê duyệt trước khi ghi vào sổ nhật ký." },
  "cashTransfer.errAmount": { id: "Jumlah pindah kas harus lebih dari 0.", en: "Transfer amount must be greater than 0.", ms: "Jumlah pindahan mesti lebih daripada 0.", th: "จำนวนโอนต้องมากกว่า 0", fil: "Ang halaga ng paglipat ay dapat higit sa 0.", vi: "Số tiền chuyển phải lớn hơn 0." },
  "cashTransfer.errSource": { id: "Pilih akun kas sumber.", en: "Select a source cash account.", ms: "Pilih akaun tunai sumber.", th: "เลือกบัญชีเงินสดต้นทาง", fil: "Pumili ng source cash account.", vi: "Chọn tài khoản tiền mặt nguồn." },
